cd "C:\Users\Billy\AppData\Local\Temp\lcm-live-rllbye9b\seed\maintenance\inputs\s05-coverage-roster" && python3 -c "
import re
def from_md(path):
    out = []
    for line in open(path, encoding='utf-8'):
        m = re.match(r'- \*\*(audit-route-s05-t02-\d+)\*\* \| System: (\S+) \| Status: (\S+) \|', line)
        if m:
            out.append(','.join(m.groups()))
    return out
def from_jsonl(path):
    import json
    out = []
    for line in open(path, encoding='utf-8'):
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        out.append(','.join([d['case'], d['system'], d['status']]))
    return out
def from_csv(path):
    import csv
    out = []
    with open(path, encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            out.append(','.join([row['case'], row['system'], row['status']]))
    return out
def from_yaml(path):
    out = []
    case = system = status = None
    for line in open(path, encoding='utf-8'):
        line = line.strip()
        if line.startswith('- case:'):
            case = line.split(':',1)[1].strip()
        elif line.startswith('system:'):
            system = line.split(':',1)[1].strip()
        elif line.startswith('status:'):
            status = line.split(':',1)[1].strip()
            out.append(','.join([case, system, status]))
    return out
def from_log(path):
    out = []
    for line in open(path, encoding='utf-8'):
        m = re.match(r'case=(\S+) system=(\S+) status=(\S+) note=', line)
        if m:
            out.append(','.join(m.groups()))
    return out

sets = {
    'md': from_md('audit-route-s05-t02-evidence-01.md'),
    'jsonl': from_jsonl('audit-route-s05-t02-evidence-02.jsonl'),
    'csv': from_csv('audit-route-s05-t02-evidence-03.csv'),
    'yaml': from_yaml('audit-route-s05-t02-evidence-04.yaml'),
    'log': from_log('audit-route-s05-t02-evidence-05.log'),
}
for name, rows in sets.items():
    print(name, 'count=', len(rows))

# overlapping range: min count across all files
n = min(len(v) for v in sets.values())
print('overlap size (cases 1..%d)' % n)
names = list(sets.keys())
mismatches = 0
for i in range(n):
    vals = {name: sets[name][i] for name in names}
    if len(set(vals.values())) != 1:
        mismatches += 1
        print('MISMATCH at index', i, vals)
print('mismatches in overlap:', mismatches)
"

