import csv, json, re

base = "maintenance/inputs/s05-ticket-history/audit-route-s05-t05-evidence-"

def parse_md(path):
    rows = {}
    pat = re.compile(r"\*\*(audit-route-s05-t05-\d{6})\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.+)$")
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = pat.search(line)
            if m:
                case, system, status, note = m.groups()
                rows[case] = (system, status, note)
    return rows

def parse_jsonl(path):
    rows = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            rows[obj["case"]] = (obj["system"], obj["status"], obj["note"])
    return rows

def parse_csv(path):
    rows = {}
    with open(path, encoding="utf-8", newline="") as f:
        for rec in csv.DictReader(f):
            rows[rec["case"]] = (rec["system"], rec["status"], rec["note"])
    return rows

def parse_yaml(path):
    rows = {}
    case = system = status = None
    note_lines = []
    def flush():
        if case:
            rows[case] = (system, status, " ".join(note_lines))
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\n")
            if line.startswith("- case:"):
                flush()
                case = line.split(":", 1)[1].strip()
                system = status = None
                note_lines = []
            elif line.strip().startswith("system:"):
                system = line.split(":", 1)[1].strip()
            elif line.strip().startswith("status:"):
                status = line.split(":", 1)[1].strip()
            elif line.strip().startswith("note:"):
                note_lines.append(line.split(":", 1)[1].strip().strip('"'))
        flush()
    return rows

def parse_log(path):
    rows = {}
    pat = re.compile(r'^case=(\S+) system=(\S+) status=(\S+) note="(.*)"$')
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = pat.match(line.strip())
            if m:
                case, system, status, note = m.groups()
                rows[case] = (system, status, note)
    return rows

sources = {
    "01.md": parse_md(base + "01.md"),
    "02.jsonl": parse_jsonl(base + "02.jsonl"),
    "03.csv": parse_csv(base + "03.csv"),
    "04.yaml": parse_yaml(base + "04.yaml"),
    "05.log": parse_log(base + "05.log"),
}

for name, rows in sources.items():
    nums = sorted(int(c.rsplit("-", 1)[1]) for c in rows)
    print(f"{name}: {len(rows)} cases, range {nums[0]:06d}-{nums[-1]:06d}, contiguous={nums == list(range(nums[0], nums[-1]+1))}")

common_max = min(max(int(c.rsplit('-',1)[1]) for c in rows) for rows in sources.values())
print(f"\nCommon overlap range: 1-{common_max}")

mismatches = []
for i in range(1, common_max + 1):
    case = f"audit-route-s05-t05-{i:06d}"
    values = {name: rows.get(case) for name, rows in sources.items()}
    if len(set(values.values())) > 1:
        mismatches.append((case, values))

print(f"Mismatches within overlap range: {len(mismatches)}")
for case, values in mismatches[:20]:
    print(case, values)
