"""Stable complete-identity helpers for compatibility repair."""

from __future__ import annotations


def complete_event_identity(recorded_at: str, content_id: str) -> str:
    """Return complete immutable event identity."""

    return "\x1f".join((recorded_at, content_id))


def durable_repair_key(actor: str, action: str, outcome: str, recorded_at: str, content_id: str) -> str:
    """Persist complete event identity for later repair."""

    return complete_event_identity(recorded_at, content_id)


def repair_group_key(stored_repair_key: str | None, recorded_at: str, content_id: str) -> str:
    """Recompute complete identity before compatibility grouping."""

    complete = complete_event_identity(recorded_at, content_id)
    if stored_repair_key == complete:
        return stored_repair_key
    return complete

"""Handoff queue and claims for recovery bundles awaiting pickup.

A queue entry references a recovery bundle by id; it never embeds or copies
the bundle's events, so the bundle stays the single append-only source of
truth. A claim records which assignee picked up a queue entry, for which
shift and ticket -- again, descriptive labels that route the handoff and
never feed event identity.
"""

from __future__ import annotations

import enum
from dataclasses import dataclass


def _require_nonempty_str(name: str, value: str) -> str:
    if not isinstance(value, str) or not value:
        raise ValueError(f"{name} must be a non-empty string")
    return value


class QueueStatus(enum.Enum):
    PENDING = "pending"
    CLAIMED = "claimed"


class ClaimStatus(enum.Enum):
    ACTIVE = "active"
    RELEASED = "released"
    COMPLETED = "completed"


@dataclass(frozen=True)
class QueueEntry:
    """One recovery bundle waiting in the handoff queue."""

    queue_entry_id: str
    bundle_id: str
    enqueued_at: str
    status: QueueStatus = QueueStatus.PENDING

    def __post_init__(self) -> None:
        _require_nonempty_str("queue_entry_id", self.queue_entry_id)
        _require_nonempty_str("bundle_id", self.bundle_id)
        _require_nonempty_str("enqueued_at", self.enqueued_at)
        if not isinstance(self.status, QueueStatus):
            raise ValueError("status must be a QueueStatus")

    def claimed(self) -> "QueueEntry":
        """Return this entry marked claimed; does not mutate ``self``."""

        return QueueEntry(self.queue_entry_id, self.bundle_id, self.enqueued_at, QueueStatus.CLAIMED)

    def reopened(self) -> "QueueEntry":
        """Return this entry marked pending again, e.g. after a claim is released."""

        return QueueEntry(self.queue_entry_id, self.bundle_id, self.enqueued_at, QueueStatus.PENDING)


@dataclass(frozen=True)
class Claim:
    """An assignee's claim on a queued recovery bundle.

    ``assignee_id``, ``shift_id``, and ``ticket_id`` are handoff labels, not
    part of any event's identity -- they say who is handling the handoff and
    under what ticket/shift, nothing more.
    """

    claim_id: str
    queue_entry_id: str
    assignee_id: str
    shift_id: str
    ticket_id: str
    claimed_at: str
    status: ClaimStatus = ClaimStatus.ACTIVE

    def __post_init__(self) -> None:
        for name in ("claim_id", "queue_entry_id", "assignee_id", "shift_id", "ticket_id", "claimed_at"):
            _require_nonempty_str(name, getattr(self, name))
        if not isinstance(self.status, ClaimStatus):
            raise ValueError("status must be a ClaimStatus")

    def released(self) -> "Claim":
        return Claim(
            self.claim_id, self.queue_entry_id, self.assignee_id,
            self.shift_id, self.ticket_id, self.claimed_at, ClaimStatus.RELEASED,
        )

    def completed(self) -> "Claim":
        return Claim(
            self.claim_id, self.queue_entry_id, self.assignee_id,
            self.shift_id, self.ticket_id, self.claimed_at, ClaimStatus.COMPLETED,
        )

"""In-memory reference implementation of ``RecoveryAuditService``.

Useful for tests and local experimentation. It enforces exactly the
invariants the interface promises -- append-only events, bundles that only
grow, claims that don't silently reassign -- the same as any other backing
store would need to.
"""

from __future__ import annotations

from typing import Dict, Iterable, List, Sequence

from .handoff_queue import Claim, ClaimStatus, QueueEntry, QueueStatus
from .models import AuditEvent
from .recovery_bundle import RecoveryBundle
from .service import (
    DuplicateEventError,
    IllegalTransitionError,
    NotFoundError,
    RecoveryAuditService,
)


class InMemoryRecoveryAuditService(RecoveryAuditService):
    def __init__(self) -> None:
        self._events: Dict[str, AuditEvent] = {}
        self._event_order: List[str] = []
        self._bundles: Dict[str, RecoveryBundle] = {}
        self._queue: Dict[str, QueueEntry] = {}
        self._queue_order: List[str] = []
        self._claims: Dict[str, Claim] = {}

    def append_event(self, event: AuditEvent) -> AuditEvent:
        existing = self._events.get(event.event_id)
        if existing is not None:
            if existing != event:
                raise DuplicateEventError(
                    f"event {event.event_id!r} already accepted with different content"
                )
            return existing
        self._events[event.event_id] = event
        self._event_order.append(event.event_id)
        return event

    def get_event(self, event_id: str) -> AuditEvent:
        try:
            return self._events[event_id]
        except KeyError:
            raise NotFoundError(f"no event {event_id!r}") from None

    def list_events(self) -> Sequence[AuditEvent]:
        return tuple(self._events[event_id] for event_id in self._event_order)

    def create_bundle(
        self,
        *,
        bundle_id: str,
        ticket_id: str,
        shift_id: str,
        assignee_id: str,
        event_ids: Iterable[str],
    ) -> RecoveryBundle:
        if bundle_id in self._bundles:
            raise IllegalTransitionError(f"bundle {bundle_id!r} already exists")
        resolved_event_ids = tuple(event_ids)
        for event_id in resolved_event_ids:
            self.get_event(event_id)
        bundle = RecoveryBundle(
            bundle_id=bundle_id,
            ticket_id=ticket_id,
            shift_id=shift_id,
            assignee_id=assignee_id,
            event_ids=resolved_event_ids,
        )
        self._bundles[bundle_id] = bundle
        return bundle

    def get_bundle(self, bundle_id: str) -> RecoveryBundle:
        try:
            return self._bundles[bundle_id]
        except KeyError:
            raise NotFoundError(f"no bundle {bundle_id!r}") from None

    def extend_bundle(self, bundle_id: str, event_ids: Iterable[str]) -> RecoveryBundle:
        bundle = self.get_bundle(bundle_id)
        for event_id in event_ids:
            self.get_event(event_id)
            bundle = bundle.with_event(event_id)
        self._bundles[bundle_id] = bundle
        return bundle

    def enqueue(self, queue_entry_id: str, bundle_id: str, enqueued_at: str) -> QueueEntry:
        if queue_entry_id in self._queue:
            raise IllegalTransitionError(f"queue entry {queue_entry_id!r} already exists")
        self.get_bundle(bundle_id)
        entry = QueueEntry(queue_entry_id=queue_entry_id, bundle_id=bundle_id, enqueued_at=enqueued_at)
        self._queue[queue_entry_id] = entry
        self._queue_order.append(queue_entry_id)
        return entry

    def list_queue(self) -> Sequence[QueueEntry]:
        return tuple(self._queue[queue_entry_id] for queue_entry_id in self._queue_order)

    def claim(
        self,
        claim_id: str,
        queue_entry_id: str,
        *,
        assignee_id: str,
        shift_id: str,
        ticket_id: str,
        claimed_at: str,
    ) -> Claim:
        if claim_id in self._claims:
            raise IllegalTransitionError(f"claim {claim_id!r} already exists")
        try:
            entry = self._queue[queue_entry_id]
        except KeyError:
            raise NotFoundError(f"no queue entry {queue_entry_id!r}") from None
        if entry.status is QueueStatus.CLAIMED:
            raise IllegalTransitionError(f"queue entry {queue_entry_id!r} is already claimed")
        claim = Claim(
            claim_id=claim_id,
            queue_entry_id=queue_entry_id,
            assignee_id=assignee_id,
            shift_id=shift_id,
            ticket_id=ticket_id,
            claimed_at=claimed_at,
        )
        self._claims[claim_id] = claim
        self._queue[queue_entry_id] = entry.claimed()
        return claim

    def _get_active_claim(self, claim_id: str) -> Claim:
        try:
            claim = self._claims[claim_id]
        except KeyError:
            raise NotFoundError(f"no claim {claim_id!r}") from None
        if claim.status is not ClaimStatus.ACTIVE:
            raise IllegalTransitionError(f"claim {claim_id!r} is not active")
        return claim

    def release_claim(self, claim_id: str) -> Claim:
        claim = self._get_active_claim(claim_id).released()
        self._claims[claim_id] = claim
        entry = self._queue[claim.queue_entry_id]
        self._queue[claim.queue_entry_id] = entry.reopened()
        return claim

