import csv
import hashlib
import json
import re
import sys

base = r"C:\Users\Billy\AppData\Local\Temp\lcm-live-rllbye9b\seed\maintenance\inputs\s05-queue-snapshots"

def sha256_of(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        h.update(f.read())
    return h.hexdigest()

def line_count(path):
    with open(path, "rb") as f:
        return sum(1 for _ in f)

def parse_md(path):
    records = {}
    pat = re.compile(
        r"^- \*\*(?P<case>[^*]+)\*\* \| System: (?P<system>[^|]+) \| Status: (?P<status>[^|]+) \| Evidence: (?P<note>.+)$"
    )
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\n")
            m = pat.match(line)
            if m:
                d = m.groupdict()
                records[d["case"]] = {
                    "system": d["system"].strip(),
                    "status": d["status"].strip(),
                    "note": d["note"].strip(),
                }
    return records

def parse_jsonl(path):
    records = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            d = json.loads(line)
            records[d["case"]] = {
                "system": d["system"],
                "status": d["status"],
                "note": d["note"],
            }
    return records

def parse_csv(path):
    records = {}
    with open(path, encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            records[row["case"]] = {
                "system": row["system"],
                "status": row["status"],
                "note": row["note"],
            }
    return records

def parse_yaml(path):
    records = {}
    current = {}
    with open(path, encoding="utf-8") as f:
        for raw in f:
            line = raw.rstrip("\n")
            if line.startswith("- case:"):
                if current.get("case"):
                    records[current["case"]] = {
                        "system": current.get("system"),
                        "status": current.get("status"),
                        "note": current.get("note"),
                    }
                current = {"case": line.split(":", 1)[1].strip()}
            elif line.strip().startswith("system:"):
                current["system"] = line.split(":", 1)[1].strip()
            elif line.strip().startswith("status:"):
                current["status"] = line.split(":", 1)[1].strip()
            elif line.strip().startswith("note:"):
                note = line.split(":", 1)[1].strip()
                if note.startswith('"') and note.endswith('"'):
                    note = note[1:-1]
                current["note"] = note
        if current.get("case"):
            records[current["case"]] = {
                "system": current.get("system"),
                "status": current.get("status"),
                "note": current.get("note"),
            }
    return records

def parse_log(path):
    records = {}
    pat = re.compile(
        r'^case=(?P<case>\S+) system=(?P<system>\S+) status=(?P<status>\S+) note="(?P<note>.+)"$'
    )
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\n")
            m = pat.match(line)
            if m:
                d = m.groupdict()
                records[d["case"]] = {
                    "system": d["system"],
                    "status": d["status"],
                    "note": d["note"],
                }
    return records

files = {
    "01.md": (f"{base}\\audit-route-s05-t07-evidence-01.md", parse_md),
    "02.jsonl": (f"{base}\\audit-route-s05-t07-evidence-02.jsonl", parse_jsonl),
    "03.csv": (f"{base}\\audit-route-s05-t07-evidence-03.csv", parse_csv),
    "04.yaml": (f"{base}\\audit-route-s05-t07-evidence-04.yaml", parse_yaml),
    "05.log": (f"{base}\\audit-route-s05-t07-evidence-05.log", parse_log),
}

parsed = {}
print("=== Per-file stats ===")
for key, (path, parser) in files.items():
    lc = line_count(path)
    digest = sha256_of(path)
    records = parser(path)
    parsed[key] = records
    case_nums = sorted(int(c.rsplit("-", 1)[1]) for c in records)
    contiguous = case_nums == list(range(1, len(case_nums) + 1))
