"""Handoff queue and claims for recovery bundles awaiting pickup.

A queue entry references a recovery bundle by id; it never embeds or copies
the bundle's events, so the bundle stays the single append-only source of
truth. A claim records which assignee picked up a queue entry, for which
shift and ticket -- again, descriptive labels that route the handoff and
never feed event identity.
"""

from __future__ import annotations

import enum
from dataclasses import dataclass


def _require_nonempty_str(name: str, value: str) -> str:
    if not isinstance(value, str) or not value:
        raise ValueError(f"{name} must be a non-empty string")
    return value


class QueueStatus(enum.Enum):
    PENDING = "pending"
    CLAIMED = "claimed"


class ClaimStatus(enum.Enum):
    ACTIVE = "active"
    RELEASED = "released"
    COMPLETED = "completed"


@dataclass(frozen=True)
class QueueEntry:
    """One recovery bundle waiting in the handoff queue."""

    queue_entry_id: str
    bundle_id: str
    enqueued_at: str
    status: QueueStatus = QueueStatus.PENDING

    def __post_init__(self) -> None:
        _require_nonempty_str("queue_entry_id", self.queue_entry_id)
        _require_nonempty_str("bundle_id", self.bundle_id)
        _require_nonempty_str("enqueued_at", self.enqueued_at)
        if not isinstance(self.status, QueueStatus):
            raise ValueError("status must be a QueueStatus")

    def claimed(self) -> "QueueEntry":
        """Return this entry marked claimed; does not mutate ``self``."""

        return QueueEntry(self.queue_entry_id, self.bundle_id, self.enqueued_at, QueueStatus.CLAIMED)

    def reopened(self) -> "QueueEntry":
        """Return this entry marked pending again, e.g. after a claim is released."""

        return QueueEntry(self.queue_entry_id, self.bundle_id, self.enqueued_at, QueueStatus.PENDING)


@dataclass(frozen=True)
class Claim:
    """An assignee's claim on a queued recovery bundle.

    ``assignee_id``, ``shift_id``, and ``ticket_id`` are handoff labels, not
    part of any event's identity -- they say who is handling the handoff and
    under what ticket/shift, nothing more.
    """

    claim_id: str
    queue_entry_id: str
    assignee_id: str
    shift_id: str
    ticket_id: str
    claimed_at: str
    status: ClaimStatus = ClaimStatus.ACTIVE

    def __post_init__(self) -> None:
        for name in ("claim_id", "queue_entry_id", "assignee_id", "shift_id", "ticket_id", "claimed_at"):
            _require_nonempty_str(name, getattr(self, name))
        if not isinstance(self.status, ClaimStatus):
            raise ValueError("status must be a ClaimStatus")

    def released(self) -> "Claim":
        return Claim(
            self.claim_id, self.queue_entry_id, self.assignee_id,
            self.shift_id, self.ticket_id, self.claimed_at, ClaimStatus.RELEASED,
        )

    def completed(self) -> "Claim":
        return Claim(
            self.claim_id, self.queue_entry_id, self.assignee_id,
            self.shift_id, self.ticket_id, self.claimed_at, ClaimStatus.COMPLETED,
        )

"""Stable complete-identity helpers for compatibility repair."""

from __future__ import annotations


def complete_event_identity(recorded_at: str, content_id: str) -> str:
    """Return complete immutable event identity."""

    return "\x1f".join((recorded_at, content_id))


def durable_repair_key(actor: str, action: str, outcome: str, recorded_at: str, content_id: str) -> str:
    """Persist complete event identity for later repair."""

    return complete_event_identity(recorded_at, content_id)


def repair_group_key(stored_repair_key: str | None, recorded_at: str, content_id: str) -> str:
    """Recompute complete identity before compatibility grouping."""

    complete = complete_event_identity(recorded_at, content_id)
    if stored_repair_key == complete:
        return stored_repair_key
    return complete

"""Request-path helpers shared by authentication and dispatch.

Versioned routes and proxy spellings should pass through one helper so a
documented path and a harmless alternate spelling reach the same decision.
"""
from __future__ import annotations

from urllib.parse import unquote


def canonical_path(raw_path: str) -> str:
    """Compatibility spelling: decode, collapse slashes, drop one trailing slash."""

    path = unquote(raw_path)
    while "//" in path:
        path = path.replace("//", "/")
    if len(path) > 1:
        path = path.rstrip("/")
    return path or "/"


def auth_path(raw_path: str) -> str:
    """Path used to look up the route table before reading a body."""

    # Look up the route using the same path spelling the rest of the service uses.
    return canonical_path(raw_path)


def dispatch_path(raw_path: str) -> str:
    """Path handed to the handler after the route decision."""

    # Hand the handler the same path the route lookup used.
    return auth_path(raw_path)

