import hashlib
import re
from pathlib import Path

base = Path(r"C:\Users\Billy\AppData\Local\Temp\lcm-live-rllbye9b\seed\maintenance\inputs\s05-abandoned-claims")

files = {
    "md": base / "audit-route-s05-t10-evidence-01.md",
    "jsonl": base / "audit-route-s05-t10-evidence-02.jsonl",
    "csv": base / "audit-route-s05-t10-evidence-03.csv",
    "yaml": base / "audit-route-s05-t10-evidence-04.yaml",
    "log": base / "audit-route-s05-t10-evidence-05.log",
}


def sha256(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def parse_md(path):
    records = {}
    pattern = re.compile(
        r"\*\*(audit-route-s05-t10-\d+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.+)$"
    )
    for line in path.read_text().splitlines():
        m = pattern.search(line)
        if m:
            case, system, status, note = m.groups()
            records[case] = {"system": system, "status": status, "note": note}
    return records


def parse_jsonl(path):
    import json
    records = {}
    for line in path.read_text().splitlines():
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        records[obj["case"]] = {"system": obj["system"], "status": obj["status"], "note": obj["note"]}
    return records


def parse_csv(path):
    import csv
    records = {}
    with path.open(newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            records[row["case"]] = {"system": row["system"], "status": row["status"], "note": row["note"]}
    return records


def parse_yaml(path):
    records = {}
    case = system = status = None
    note_lines = []
    in_note = False

    def flush():
        if case is not None:
            records[case] = {"system": system, "status": status, "note": "".join(note_lines)}

    for raw in path.read_text().splitlines():
        if raw.startswith("- case:"):
            flush()
            case = raw.split(":", 1)[1].strip()
            system = status = None
            note_lines = []
        elif raw.strip().startswith("system:"):
            system = raw.split(":", 1)[1].strip()
        elif raw.strip().startswith("status:"):
            status = raw.split(":", 1)[1].strip()
        elif raw.strip().startswith("note:"):
            note = raw.split(":", 1)[1].strip()
            note_lines = [note.strip('"')]
    flush()
    return records


def parse_log(path):
    records = {}
    pattern = re.compile(
        r'case=(\S+) system=(\S+) status=(\S+) note="(.+)"$'
    )
    for line in path.read_text().splitlines():
        m = pattern.search(line)
        if m:
            case, system, status, note = m.groups()
            records[case] = {"system": system, "status": status, "note": note}
    return records


parsers = {
    "md": parse_md,
    "jsonl": parse_jsonl,
    "csv": parse_csv,
    "yaml": parse_yaml,
    "log": parse_log,
}

parsed = {}
for key, path in files.items():
    line_count = len(path.read_text().splitlines())
    digest = sha256(path)
    records = parsers[key](path)
    parsed[key] = records
    case_nums = sorted(int(c.rsplit("-", 1)[1]) for c in records)
    contiguous = case_nums == list(range(1, len(case_nums) + 1)) if case_nums else False
    print(f"{key}: file={path.name} lines={line_count} sha256={digest} records={len(records)} "
          f"min={case_nums[0] if case_nums else None} max={case_nums[-1] if case_nums else None} "
          f"contiguous_from_1={contiguous}")

# Cross-file comparison over the shortest file's case range
shortest_key = min(parsed, key=lambda k: len(parsed[k]))
shortest_count = len(parsed[shortest_key])
print(f"\nShortest file (by record count): {shortest_key} ({shortest_count} records) -- comparing cases 1..{shortest_count}")

mismatches = 0
for i in range(1, shortest_count + 1):
    case_id = f"audit-route-s05-t10-{i:06d}"
    values = {}
    for key in files:
        rec = parsed[key].get(case_id)
        if rec is None:
            print(f"MISSING: {case_id} absent from {key}")
            mismatches += 1
            continue
        values[key] = (rec["system"], rec["status"])
    unique_values = set(values.values())
    if len(unique_values) > 1:
        print(f"MISMATCH at {case_id}: {values}")
        mismatches += 1

print(f"\nTotal mismatches/missing over cases 1..{shortest_count}: {mismatches}")

