import csv
import hashlib
import json
import re

BASE = r"C:\Users\Billy\AppData\Local\Temp\lcm-live-rllbye9b\seed\maintenance\inputs\s05-morning-packet"

FILES = {
    "md": f"{BASE}\\audit-route-s05-t14-evidence-01.md",
    "jsonl": f"{BASE}\\audit-route-s05-t14-evidence-02.jsonl",
    "csv": f"{BASE}\\audit-route-s05-t14-evidence-03.csv",
    "yaml": f"{BASE}\\audit-route-s05-t14-evidence-04.yaml",
    "log": f"{BASE}\\audit-route-s05-t14-evidence-05.log",
}


def sha256(path):
    with open(path, "rb") as f:
        return hashlib.sha256(f.read()).hexdigest()


def line_count(path):
    with open(path, "r", encoding="utf-8") as f:
        return sum(1 for _ in f)


def parse_md(path):
    cases = {}
    pattern = re.compile(r"\*\*(audit-route-s05-t14-\d+)\*\* \| System: ([\w-]+) \| Status: ([\w-]+) \|")
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = pattern.search(line)
            if m:
                cases[m.group(1)] = (m.group(2), m.group(3))
    return cases


def parse_jsonl(path):
    cases = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            cases[obj["case"]] = (obj["system"], obj["status"])
    return cases


def parse_csv(path):
    cases = {}
    with open(path, encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            cases[row["case"]] = (row["system"], row["status"])
    return cases


def parse_yaml(path):
    cases = {}
    current = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\n")
            if line.startswith("- case:"):
                if current.get("case"):
                    cases[current["case"]] = (current["system"], current["status"])
                current = {"case": line.split(":", 1)[1].strip()}
            elif line.strip().startswith("system:"):
                current["system"] = line.split(":", 1)[1].strip()
            elif line.strip().startswith("status:"):
                current["status"] = line.split(":", 1)[1].strip()
    if current.get("case"):
        cases[current["case"]] = (current["system"], current["status"])
    return cases


def parse_log(path):
    cases = {}
    pattern = re.compile(r"case=(audit-route-s05-t14-\d+) system=([\w-]+) status=([\w-]+)")
    with open(path, encoding="utf-8") as f:
        for line in f:
            m = pattern.search(line)
            if m:
                cases[m.group(1)] = (m.group(2), m.group(3))
    return cases


parsers = {"md": parse_md, "jsonl": parse_jsonl, "csv": parse_csv, "yaml": parse_yaml, "log": parse_log}

print("=== line counts / sha256 ===")
for key, path in FILES.items():
    print(key, line_count(path), sha256(path))

parsed = {key: parsers[key](path) for key, path in FILES.items()}

print()
print("=== case counts per file ===")
for key, cases in parsed.items():
    nums = sorted(int(c.rsplit("-", 1)[1]) for c in cases)
    contiguous = nums == list(range(1, len(nums) + 1))
    print(key, "count=", len(cases), "min=", nums[0], "max=", nums[-1], "contiguous_from_1=", contiguous)

shortest_key = min(parsed, key=lambda k: len(parsed[k]))
shortest_n = len(parsed[shortest_key])
print()
print(f"=== cross-file comparison over shortest range: {shortest_key} (1..{shortest_n}) ===")

mismatches = []
for i in range(1, shortest_n + 1):
    case_id = f"audit-route-s05-t14-{i:06d}"
    values = {key: parsed[key].get(case_id) for key in parsed}
    if len(set(values.values())) > 1:
        mismatches.append((case_id, values))

print("mismatches:", len(mismatches))
for m in mismatches[:20]:
    print(m)
